/**
 * The demo question is the product's central proof, so its correctness is
 * locked here rather than trusted to review.
 *
 * `validateQuestion` holds the explanation to the answer key (AE2). That is a
 * self-consistency check, not a maths check: it cannot tell a correct puzzle
 * from a wrong one that merely agrees with itself. The rule checks below are
 * what actually verify the board — every filled cell is generated by the stated
 * rule, the key is what the rule produces along the missing cell's row *and*
 * down its column, and every distractor breaks exactly one thing.
 */
import { demoMatrixQuestion } from "@/content/demo/matrix-question";
import { validateQuestion } from "@/lib/questions/validate";
import type { FigureGlyph, QuarterTurns } from "@/content/questions/types";

const question = demoMatrixQuestion;

function cellAt(rowIndex: number, columnIndex: number) {
  const cell = question.visual.rows[rowIndex]?.[columnIndex];
  if (cell === undefined) {
    throw new Error(`no cell at row ${rowIndex} column ${columnIndex}`);
  }
  return cell;
}

function glyphAt(rowIndex: number, columnIndex: number): FigureGlyph {
  const { glyph } = cellAt(rowIndex, columnIndex);
  if (glyph === null) {
    throw new Error(`cell r${rowIndex + 1}c${columnIndex + 1} was expected to hold a figure`);
  }
  return glyph;
}

const keyedGlyph = (): FigureGlyph => {
  const choice = question.choices.find((entry) => entry.id === question.correctChoiceId);
  if (choice === undefined) {
    throw new Error("the answer key names a choice that does not exist");
  }
  return choice.glyph;
};

const turns = (glyph: FigureGlyph): QuarterTurns => glyph.quarterTurns;

/**
 * What a glyph looks like, stripped of its identity. Two glyphs are the same
 * figure when these three fields match; `glyphId` and `altText` name a
 * particular picture rather than the shape of it.
 */
const figureOf = (glyph: FigureGlyph) => ({
  shape: glyph.shape,
  fill: glyph.fill,
  quarterTurns: glyph.quarterTurns,
});

describe("the landing demo matrix", () => {
  it("validates against validateQuestion, so the key and the explanation agree", () => {
    const result = validateQuestion(question);

    expect(result.issues).toEqual([]);
    expect(result.valid).toBe(true);
  });

  it("has exactly one empty cell, and it is the bottom-right square", () => {
    const empty = question.visual.rows
      .flat()
      .filter((cell) => cell.glyph === null)
      .map((cell) => cell.cellId);

    expect(empty).toEqual([question.visual.missingCellId]);
    expect(question.visual.missingCellId).toBe("cell-r3c3");
  });

  it("generates every filled cell from the stated rule: each step right or down is a quarter turn", () => {
    const board = question.visual.rows.flatMap((row, rowIndex) =>
      row.map((cell, columnIndex) => ({ cell, rowIndex, columnIndex })),
    );

    const wrong = board
      .filter(({ cell }) => cell.glyph !== null)
      .filter(
        ({ cell, rowIndex, columnIndex }) =>
          cell.glyph !== null &&
          cell.glyph.quarterTurns !== ((rowIndex + columnIndex) % 4),
      )
      .map(({ cell }) => cell.cellId);

    expect(wrong).toEqual([]);
  });

  it("derives the answer key along the missing cell's row", () => {
    // Row 3 holds down(2), left(3) and the empty square. The step between the
    // two filled cells is the rule; applying it once more gives the key.
    const step = (turns(glyphAt(2, 1)) - turns(glyphAt(2, 0)) + 4) % 4;
    const derived = figureOf(glyphAt(2, 1));

    expect(step).toBe(1);
    expect({ ...derived, quarterTurns: (derived.quarterTurns + step) % 4 }).toEqual(
      figureOf(keyedGlyph()),
    );
    expect(keyedGlyph().altText).toBe("an outlined arrow pointing up");
  });

  it("derives the answer key down the missing cell's column", () => {
    // Column 3 holds down(2), left(3) and the empty square: the same step,
    // reached from the other direction, and it lands on the same figure.
    const step = (turns(glyphAt(1, 2)) - turns(glyphAt(0, 2)) + 4) % 4;
    const derived = figureOf(glyphAt(1, 2));

    expect(step).toBe(1);
    expect({ ...derived, quarterTurns: (derived.quarterTurns + step) % 4 }).toEqual(
      figureOf(keyedGlyph()),
    );
  });

  it("keeps the shape and the filling constant across the whole board", () => {
    const filled = question.visual.rows.flatMap((row) =>
      row.flatMap((cell) => (cell.glyph === null ? [] : [cell.glyph])),
    );
    const shapes = new Set(filled.map((glyph) => glyph.shape));
    const fills = new Set(filled.map((glyph) => glyph.fill));

    expect(filled).toHaveLength(8);
    expect([...shapes]).toEqual(["arrow"]);
    expect([...fills]).toEqual(["outline"]);
  });

  it("makes every wrong choice break exactly one thing", () => {
    const keyed = keyedGlyph();

    const differences = question.choices
      .filter((choice) => choice.id !== question.correctChoiceId)
      .map((choice) => ({
        id: choice.id,
        altText: choice.glyph.altText,
        breaks: [
          choice.glyph.shape !== keyed.shape && "shape",
          choice.glyph.fill !== keyed.fill && "filling",
          choice.glyph.quarterTurns !== keyed.quarterTurns && "direction",
        ].filter(Boolean),
      }));

    expect(differences).toEqual([
      { id: "b", altText: "an outlined arrow pointing left", breaks: ["direction"] },
      { id: "c", altText: "an outlined arrow pointing down", breaks: ["direction"] },
      { id: "d", altText: "a solid arrow pointing up", breaks: ["filling"] },
    ]);
  });

  it("names the keyed choice in the plain-language rule text at the end of the walkthrough", () => {
    const last = question.explanation[question.explanation.length - 1];

    expect(last?.operation).toBe("state-rule");
    expect(last?.narration).toMatch(/quarter turn clockwise/);
  });
});